import { useEffect, useRef, useCallback, useState } from 'react'
import { Howler, Howl } from 'howler'
import { useInteractionStore } from '../store/useInteractionStore'

/** Sound keys generated by scripts/generate-sounds.mjs. */
export type SoundKey =
  | 'click'
  | 'servo'
  | 'greet'
  | 'happy'
  | 'curious'
  | 'sleep'
  | 'explore'
  | 'dance'
  | 'ambience'

const FILES: Record<SoundKey, string> = {
  click: '/sounds/click.wav',
  servo: '/sounds/servo.wav',
  greet: '/sounds/greet.wav',
  happy: '/sounds/happy.wav',
  curious: '/sounds/curious.wav',
  sleep: '/sounds/sleep.wav',
  explore: '/sounds/explore.wav',
  dance: '/sounds/dance.wav',
  ambience: '/sounds/ambience.wav',
}

const LOOPED: SoundKey[] = ['ambience']

/**
 * Lazily loads each sound on first use and plays it only while the visitor
 * has sound enabled. Howler instances are cached; ambience loops seamlessly.
 */
export function useSound() {
  const enabled = useInteractionStore((s) => s.soundEnabled)
  const howls = useRef(new Map<SoundKey, Howl>())
  const [ready, setReady] = useState(false)

  // Unlock audio on the first user gesture (browser autoplay policy).
  useEffect(() => {
    const unlock = () => setReady(true)
    window.addEventListener('pointerdown', unlock, { once: true })
    window.addEventListener('keydown', unlock, { once: true })
    return () => {
      window.removeEventListener('pointerdown', unlock)
      window.removeEventListener('keydown', unlock)
    }
  }, [])

  // Global volume / suspension tied to the toggle.
  useEffect(() => {
    Howler.volume(enabled ? 0.8 : 0)
    if (!enabled) Howler.stop()
  }, [enabled])

  const get = useCallback((key: SoundKey): Howl => {
    let h = howls.current.get(key)
    if (!h) {
      h = new Howl({
        src: [FILES[key]],
        loop: LOOPED.includes(key),
        volume: LOOPED.includes(key) ? 0.35 : 0.9,
        onloaderror: (_id, err) => console.warn(`[sound] failed to load ${key}`, err),
      })
      howls.current.set(key, h)
    }
    return h
  }, [])

  const play = useCallback(
    (key: SoundKey) => {
      if (!enabled || !ready) return
      const h = get(key)
      if (!h.playing()) h.play()
    },
    [enabled, ready, get],
  )

  const stop = useCallback((key: SoundKey) => {
    howls.current.get(key)?.stop()
  }, [])

  // Start / stop ambience with the toggle.
  useEffect(() => {
    if (enabled && ready) {
      get('ambience').play()
    } else {
      stop('ambience')
    }
  }, [enabled, ready, get, stop])

  return { play, stop, enabled }
}
